async function crawlNaive(queue) {
  while (!queue.isEmpty()) {
    const url = await queue.pop();          // consecutive URLs share a host
    const html = await fetch(url);
    for (const link of extractLinks(html)) queue.push(link);
  }
}

// A global delay fixes politeness and destroys throughput:
// now the whole crawler fetches one page per interval.

// FRONT queues → priority bands (PageRank, update rate, staleness)
// BACK queues  → exactly one per host, one worker each

const backQueueFor = new Map();   // hostname → queue id
const nextEligibleAt = new Map(); // queue id  → timestamp

function routeToBack(url) {
  const host = new URL(url).hostname;
  backQueueFor.set(host, backQueueFor.get(host) ?? allocateQueue(host));
  return backQueueFor.get(host);
}

function nextEligibleQueue(now = Date.now()) {
  for (const [qid, readyAt] of nextEligibleAt) {
    if (readyAt <= now && !isEmpty(qid)) return qid;
  }
  return null;                       // everything is cooling down
}

function markFetched(qid, host, responseMs) {
  // adapt: a slow server is crawled more gently, automatically
  const delay = Math.max(1000, responseMs * 10);
  nextEligibleAt.set(qid, Date.now() + delay);
}

function normalise(raw) {
  const u = new URL(raw);
  u.hash = '';                       // fragments aren't separate pages
  u.hostname = u.hostname.toLowerCase();
  if ((u.protocol === 'http:'  && u.port === '80') ||
      (u.protocol === 'https:' && u.port === '443')) u.port = '';

  for (const p of ['utm_source', 'utm_medium', 'sessionid', 'sid']) {
    u.searchParams.delete(p);        // volatile → would look novel forever
  }
  u.searchParams.sort();
  return u.toString();
}

function seenBefore(filter, url) {
  const key = normalise(url);
  if (filter.has(key)) return true;  // 'probably seen' — may be wrong ~1%
  filter.add(key);
  return false;                      // 'definitely new' — never wrong
}

// ~1.2 GB holds ~1B URLs at a 1% false-positive rate.
// Exact membership would be an order of magnitude more.

async function crawl(frontier, filter, store) {
  while (true) {
    const qid = nextEligibleQueue();
    if (!qid) { await sleep(50); continue; }

    const url = frontier.pop(qid);
    const started = Date.now();
    const html = await fetch(url);
    markFetched(qid, new URL(url).hostname, Date.now() - started);

    const digest = sha256(html);
    if (await store.digestChanged(url, digest)) await store.put(url, html, digest);

    for (const link of extractLinks(html)) {
      if (!seenBefore(filter, link) && withinBudget(link)) {
        frontier.push(routeToBack(link), link);
      }
    }
  }
}

const MAX_DEPTH = 8;
const MAX_PAGES_PER_HOST = 100_000;

function withinBudget(url) {
  const host = new URL(url).hostname;
  return depthOf(url) <= MAX_DEPTH && pagesSeen(host) < MAX_PAGES_PER_HOST;
}

